import { afterAll, beforeAll, expect, test } from 'vitest'
import { chromium, type Browser } from 'playwright'
import { getPlatformProxy } from 'wrangler'
import server from '../../server'
import { applyMigrations } from '../db/test-migrations'
import { TEST_ORIGIN, testEnv } from '../publication/test-support'
import { japaneseOutside } from './test-japanese'

// The pages are generated by `pnpm build`; CI builds before testing.
const platform = await getPlatformProxy<Env>({ persist: false })
const env = testEnv(platform.env)

let browser: Browser
beforeAll(async () => {
  await applyMigrations(platform.env.DB)
  browser = await chromium.launch()
})
afterAll(async () => {
  await browser?.close()
  await platform.dispose()
})

/** Opens the top page through the Worker, so the page CSP applies. */
async function openTop(path: string) {
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
  const errors: string[] = []
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text())
  })
  page.on('pageerror', (error) => errors.push(error.message))
  await page.route('**/*', async (route) => {
    const url = new URL(route.request().url())
    if (url.origin !== TEST_ORIGIN) return route.abort()
    // Miniflare's local proxy refuses a foreign Origin; see home.browser.test.
    const { origin: _origin, ...headers } = await route.request().allHeaders()
    const response = await server.fetch(new Request(url, { headers }), env)
    await route.fulfill({
      status: response.status,
      headers: Object.fromEntries(response.headers),
      body: Buffer.from(await response.arrayBuffer()),
    })
  })
  await page.goto(`${TEST_ORIGIN}${path}`)
  await page.waitForLoadState('networkidle')
  const demo = page.locator('#touch-demo').locator('xpath=../..')
  return { page, demo, errors }
}

const japanese = (total: string) => `合計 ${total}`
const english = (total: string) => `${total} in total`

test.each([
  ['/?lang=ja', japanese, '3回目'],
  ['/?lang=en', english, 'Try 3'],
] as const)(
  'Given the top page %s, When the reader moves the sliders, Then the waits and the total follow under the page CSP',
  async (path, total, third) => {
    const { page, demo, errors } = await openTop(path)
    const note = demo.locator('.mock-note')
    const items = demo.locator('.mock-timeline li')
    const [factor, tries] = await demo.locator('input[type=range]').all()
    // Factor 2, 5 tries: 0 + 0.5 + 1 + 2 + 4 seconds.
    await expect.poll(() => note.textContent()).toContain(total('7.5s'))
    expect(await items.count()).toBe(5)

    await tries!.fill('3')
    // 0 + 0.5 + 1 seconds.
    await expect.poll(() => note.textContent()).toContain(total('1.5s'))
    expect(await items.count()).toBe(3)
    expect(await items.last().locator('b').textContent()).toBe(third)
    expect(await items.last().locator('small').textContent()).toBe('+1s')

    await factor!.fill('3')
    // 0 + 0.5 + 1.5 seconds.
    await expect.poll(() => note.textContent()).toContain(total('2s'))
    await tries!.fill('4')
    // ... + 4.5 seconds before the fourth try.
    await expect.poll(() => note.textContent()).toContain(total('6.5s'))

    if (path.endsWith('en'))
      expect(japaneseOutside(await page.content())).toEqual([])
    // Nothing moves out of the slide frame at phone width.
    const overflow = await page.evaluate(
      () => document.documentElement.scrollWidth - window.innerWidth,
    )
    expect(overflow).toBeLessThanOrEqual(0)
    expect(errors).toEqual([])
    await page.close()
  },
)
